//! The POD image: `struct Tex` holds every WEB global.  Generated by tools/webgen.py; frozen
//! after M0.  Do not add fields here.  A module adds its own state to the `Vars` struct in
//! its own file (docs/PORTING.md, "Adding a global").
//!
//! Types per the key type decision: every integer-like WEB type is `i32`, `boolean` is `bool`,
//! `longinteger` is `i64`, `real` and `glue_ratio` are `f64`.  Arrays are inline and fixed.
//! The exceptions are the sums of glue and of line breaking, in `WIDE_GLOBALS`: docs/PORTING.md section 11.
//! Not here: file variables (Host), `help_line` (Host), `mem_bot`..`mem_max` (consts), and
//! `pdf_buf` (a pointer in WEB; `pdf_buf_is_os` selects pdf_os_buf or pdf_op_buf).
#![forbid(unsafe_code)]
#![allow(non_snake_case, dead_code)]

use crate::consts::*;
use crate::host::Host;
use crate::raw::*;

// Capacities.  Virtual only: the mapping commits lazily.  The web2c size variables
// (pool_size, stack_size, ...) remain fields, default to these, and may be set lower.
/// mem words, 256 MiB; lo below MEM_SPLIT, hi above
pub const MEM_CAP: usize = 33554432;
/// toks heap cells, 256 MiB
pub const TOKS_CAP: usize = 1 << 26;
/// builder stack cells, 64 MiB
pub const TB_CAP: usize = 1 << 24;
/// transient token stack cells, 16 MiB
pub const TX_CAP: usize = 1 << 22;
/// eqtb and text entries; run-time control sequences live above EQTB_SIZE
pub const EQTB_CAP: usize = 1 << 21;
/// open-addressing hash slots, a power of two
pub const HASH_TAB_CAP: usize = 1 << 22;
/// str_pool bytes
pub const POOL_CAP: usize = 1 << 26;
/// str_start entries; ssup_max_strings+2
pub const STR_CAP: usize = 2097152 + 2;
/// buffer bytes
pub const BUF_CAP: usize = 1 << 24;
/// sup_nest_size+1
pub const NEST_CAP: usize = 4001;
/// save_stack words
pub const SAVE_CAP: usize = 1 << 21;
/// sup_stack_size+1
pub const STACK_CAP: usize = 30001;
/// sup_max_in_open+1
pub const MAX_IN_OPEN_CAP: usize = 128;
/// sup_param_size+1
pub const PARAM_CAP: usize = 32768;
/// max_font_max+1
pub const FONT_CAP: usize = 9001;
/// font_info words
pub const FONT_MEM_CAP: usize = 1 << 24;
/// ssup_trie_size+1
pub const TRIE_CAP: usize = 0x400000;
/// ssup_hyph_size+1
pub const HYPH_CAP: usize = 65536;
/// sup_dvi_buf_size+1
pub const DVI_BUF_CAP: usize = 65537;
/// sup_pdf_mem_size+1
pub const PDF_MEM_CAP: usize = 10000001;
/// sup_pdf_os_buf_size+1
pub const PDF_OS_BUF_CAP: usize = 5000001;
/// sup_obj_tab_size+1
pub const OBJ_TAB_CAP: usize = 8388608;
/// sup_dest_names_size+1
pub const DEST_NAMES_CAP: usize = 500001;
/// name_of_file bytes
pub const FILE_NAME_CAP: usize = 65536;
/// general POD arena words (u64), 512 MiB; see arena_vec
pub const ARENA_CAP: usize = 1 << 26;

